// CONFIDENCE: MEDIUM. Native body (196-line capture). Delegate bindings use the UE dynamic-delegate pattern.
if (IsExplosionBroadcastBlocked() || IsDefaultObjectFlag()) return;   // vslot 0x658 and object-flag bit at +0x8 bit 0x10
UPrimitiveComponent* Old = CollisionComponent;                      // raw this+0x3f0 (param_1[0x7e])
if (Old != nullptr)
{
    // Unbind the three component delegates from the old component. Each unbind is conditional on a per-delegate bool byte: 0x3b8 (OnComponentHit), 0x3b9 (OnComponentBeginOverlap), 0x3ba (OnComponentEndOverlap).
    if (BoundHit)        Old->OnComponentHit.RemoveDynamic(this, &AFortGameplayEffectDeliveryActor::OnComponentTouch);
    if (BoundBeginOverlap) Old->OnComponentBeginOverlap.RemoveDynamic(this, &AFortGameplayEffectDeliveryActor::OnComponentOverlap);
    if (BoundEndOverlap)   Old->OnComponentEndOverlap.RemoveDynamic(this, &AFortGameplayEffectDeliveryActor::OnComponentEndOverlap);
}
CollisionComponent = NewCollisionComponent;
if (NewCollisionComponent != nullptr)
{
    // Bind OnComponentTouch to OnComponentHit, OnComponentOverlap to OnComponentBeginOverlap, and OnComponentEndOverlap when raw flag 0x200 on this+0x7c is set.
    // Binding flags are set in the same bytes (0x3b8 / 0x3b9 / 0x3ba) with a bitwise OR of the bind result.
    NewCollisionComponent->OnComponentHit.AddDynamic(this, &AFortGameplayEffectDeliveryActor::OnComponentTouch);
    NewCollisionComponent->OnComponentBeginOverlap.AddDynamic(this, &AFortGameplayEffectDeliveryActor::OnComponentOverlap);
    if (FlagWord3E0 & 0x200)   // raw this+0x3e0 bit 0x200 (header bRegisterForEndOverlaps, LOW)
        NewCollisionComponent->OnComponentEndOverlap.AddDynamic(this, &AFortGameplayEffectDeliveryActor::OnComponentEndOverlap);
}
if (Role != ROLE_Authority && (FlagWord3E0 & 0x20) && CollisionComponent != nullptr)   // raw this+0x3e0 bit 0x20 (header bDisableClientOverlapEvents, LOW)
    CollisionComponent->SetGenerateOverlapEvents(false);
UpdateCollisionState();   // FUN_1426ba960 (not ported)
